package es.educacion.orm;
import es.educacion.orm.config.EntityManagerFactories; import es.educacion.orm.model.Producto; import es.educacion.orm.orm.ProductoOrmRepository; import es.educacion.orm.repository.IProductoRepository; import jakarta.persistence.EntityManagerFactory; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import java.nio.file.Path; import static org.junit.jupiter.api.Assertions.*;
class ProductoOrmRepositoryTest { @TempDir Path temp; @Test void crudCompleto(){try(EntityManagerFactory emf=EntityManagerFactories.forTest(temp.resolve("orm.db"))){IProductoRepository r=new ProductoOrmRepository(emf);r.create(new Producto(1,"Teclado",30));assertEquals(1,r.findAll().size());assertTrue(r.update(new Producto(1,"Teclado mecánico",50)));assertEquals(50,r.findById(1L).orElseThrow().precio());assertTrue(r.delete(1L));assertTrue(r.findAll().isEmpty());}} }